# Generated by Selenium IDE & Refined for EduSphere Testing
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.support.wait import WebDriverWait

class TestTimetableee():
    def setup_method(self, method):
        options = webdriver.ChromeOptions()
        options.add_argument("--start-maximized")
        # Ensure notifications / popups don't interfere
        options.add_argument("--disable-notifications")
        self.driver = webdriver.Chrome(options=options)
        self.vars = {}

    def teardown_method(self, method):
        if hasattr(self, "driver"):
            self.driver.quit()

    def test_timetableee(self):
        driver = self.driver
        wait = WebDriverWait(driver, 20)

        # 1. First Login as Administrator to establish session
        driver.get("http://localhost:5173/login")
        wait.until(EC.presence_of_element_located((By.NAME, "email")))

        email_input = driver.find_element(By.NAME, "email")
        email_input.clear()
        email_input.send_keys("melbin@gmail.com")

        password_input = driver.find_element(By.NAME, "password")
        password_input.clear()
        password_input.send_keys("123456")

        submit_btn = wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[@type='submit']"))
        )
        submit_btn.click()

        # 2. Wait for login redirect
        wait.until(EC.url_contains("/administrator"))

        # 3. Navigate to the Timetable Allocation page
        driver.get("http://localhost:5173/administrator/timetable")

        # 4. Wait for Allocation Settings controls to render
        neet_btn = wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'NEET')]"))
        )
        driver.execute_script("arguments[0].click();", neet_btn)

        # Select Morning Batch
        morning_btn = wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Morning')]"))
        )
        driver.execute_script("arguments[0].click();", morning_btn)

        # Optional: Add extra subject if input present
        try:
            extra_input = driver.find_element(By.XPATH, "//input[@placeholder and contains(@placeholder, 'English')]")
            extra_input.clear()
            extra_input.send_keys("Computer Science")
        except Exception:
            pass

        time.sleep(1)

        # 5. Locate and click "Auto-Allocate Timetable" button using JS click for React reliability
        generate_btn = wait.until(
            EC.presence_of_element_located(
                (By.XPATH, "//button[contains(., 'Auto-Allocate') or contains(., 'Generate')]")
            )
        )
        driver.execute_script("arguments[0].scrollIntoView({block: 'center'});", generate_btn)
        time.sleep(0.5)
        driver.execute_script("arguments[0].click();", generate_btn)

        # 6. Wait for timetable schedule to appear
        # TimetableGenerator has a 1.5s simulated delay, then displays "Allocated Successfully" and "Monday"
        wait.until(
            lambda d: "Allocated Successfully" in d.find_element(By.TAG_NAME, "body").text or 
                      "Monday" in d.find_element(By.TAG_NAME, "body").text
        )

        # 7. Assertions to verify schedule generation
        body_text = driver.find_element(By.TAG_NAME, "body").text
        assert "Monday" in body_text, "Timetable failed to display Monday schedule"
        assert any(sub in body_text for sub in ["Physics", "Chemistry", "Botany", "Zoology", "Mock Test", "Computer Science"]), "Expected subjects not found in timetable"

        print("\n[SUCCESS] TIMETABLE TEST PASSED! Weekly schedule generated and verified successfully.")

if __name__ == "__main__":
    pytest.main(["test_timetableee.py", "-v", "-s"])
